 // A commitPipeline manages the stages of committing a set of mutations
@@ -314,6 +318,7 @@ func (p *commitPipeline) Commit(b *Batch, syncWAL bool, noSyncWait bool) error {
 	//
 	// NB: We set Batch.commitErr on error so that the batch won't be a candidate
 	// for reuse. See Batch.release().
+	syncStartTime := crtime.NowMono()
 	mem, err := p.prepare(b, syncWAL, noSyncWait)
 	if err != nil {
 		b.db = nil // prevent batch reuse on error
@@ -350,6 +355,20 @@ func (p *commitPipeline) Commit(b *Batch, syncWAL bool, noSyncWait bool) error {

 	b.commitStats.TotalDuration = commitStartTime.Elapsed()

+	if syncWAL && !p.env.disableWAL && p.env.onBatchDurable != nil {
+		applyDuration := crtime.NowMono().Sub(commitStartTime)
+		if !noSyncWait {
+			syncDuration := crtime.NowMono().Sub(syncStartTime)
+			p.env.onBatchDurable(b, err, applyDuration, syncDuration)
