+				b.fsyncWait.Wait()
+				syncDur := crtime.NowMono().Sub(syncStart)
+				p.env.onBatchDurable(b, b.commitErr, applyDur, syncDur)
+			}(b, syncStartTime, applyDuration)
+		}
+	}
+
