+	if d.durability == nil {
+		return nil
+	}
+	return d.durability.WaitForDurabilityBatchContext(ctx, seqs)
+}
+
+// WaitForJobDurability blocks until the batch commit for jobID is durable.
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.WaitForJobDurabilityContext(context.Background(), jobID)
+}
+
+// WaitForJobDurabilityContext blocks until the batch commit for jobID is durable or ctx is cancelled.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	if d.durability == nil {
+		return nil
+	}
+	return d.durability.WaitForJobDurabilityContext(ctx, jobID)
+}
+
+// DurableState returns the highest durable sequence number and first latched error.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	if d.durability == nil {
+		return 0, nil
+	}
+	return d.durability.DurableState()
+}
+
+// DurabilityNotify returns a channel that receives nil on durability or non-nil error on failure/close.
+func (d *DB) DurabilityNotify(seq base.SeqNum) <-chan error {
+	if d.durability == nil {
+		ch := make(chan error, 1)
+		ch <- nil
+		return ch
+	}
+	return d.durability.DurabilityNotify(seq)
+}
+
+// DurabilityStats returns a snapshot of durability statistics.
+func (d *DB) DurabilityStats() DurabilityStats {
+	if d.durability == nil {
+		return DurabilityStats{}
+	}
+	return d.durability.DurabilityStats()
+}
diff --git a/durability.go b/durability.go
new file mode 100644
index 00000000..b4bac8b6
--- /dev/null
+++ b/durability.go
@@ -0,0 +1,492 @@
+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"sync/atomic"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+// DurabilityStats holds a snapshot of durability statistics.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration        time.Duration
+}
+
+const (
+	maxJobRetention  = 10000
+	maxSubscriptions = 4096
+)
+
+type durabilityManager struct {
+	mu sync.Mutex
+
+	d                      *DB
+	batchDurableConfigured bool
+	disabled               bool
+
+	highestDurableSeqNum   base.SeqNum
+	firstErr               error
+	totalCommits           uint64
+	totalDurableCommits    uint64
+	totalFailedCommits     uint64
+	cumulativeSyncDuration time.Duration
+	maxSyncDuration        time.Duration
+
+	pendingWaiters atomic.Int64
+
+	minTrackedJobID  int
+	maxAssignedJobID int
+	jobResults       map[int]durabilityJobResult
+
+	waiters       []*durabilityWaiter
+	subscriptions map[chan error]base.SeqNum
+}
+
+type durabilityJobResult struct {
+	done bool
+	err  error
+}
+
+type durabilityWaiter struct {
+	isJob bool
+	seq   base.SeqNum
+	jobID int
+	ch    chan struct{}
+}
+
+func newDurabilityManager(d *DB, batchDurableConfigured bool, disabled bool) *durabilityManager {
+	return &durabilityManager{
+		d:                      d,
+		batchDurableConfigured: batchDurableConfigured,
+		disabled:               disabled,
+		jobResults:             make(map[int]durabilityJobResult),
+		subscriptions:          make(map[chan error]base.SeqNum),
+	}
+}
+
+func (m *durabilityManager) registerJobID(jobID int) {
+	if jobID <= 0 {
+		return
+	}
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if jobID > m.maxAssignedJobID {
+		m.maxAssignedJobID = jobID
+	}
+	if m.minTrackedJobID == 0 {
+		m.minTrackedJobID = jobID
+	}
+	m.jobResults[jobID] = durabilityJobResult{done: false}
+}
+
+func (m *durabilityManager) onBatchDurable(
+	b *Batch, err error, applyDuration, syncDuration time.Duration,
+) {
+	if m.disabled {
+		return
+	}
+
+	jobID := b.commitJobID
+	seqNum := b.SeqNum()
+	count := b.Count()
+	correlationID := b.commitCorrelationID
+	batchSize := len(b.Repr())
+
+	if applyDuration <= 0 && err == nil {
+		applyDuration = 1 * time.Nanosecond
+	}
+	if syncDuration <= 0 && err == nil {
+		syncDuration = 1 * time.Nanosecond
+	}
+
+	var batchHighest base.SeqNum
+	if count > 0 {
+		batchHighest = seqNum + base.SeqNum(count) - 1
+	} else {
+		batchHighest = seqNum
+	}
+
+	m.mu.Lock()
+
+	m.totalCommits++
+	if err != nil {
+		m.totalFailedCommits++
+		if m.firstErr == nil {
+			m.firstErr = err
+		}
+	} else {
+		m.totalDurableCommits++
+		if batchHighest > m.highestDurableSeqNum {
+			m.highestDurableSeqNum = batchHighest
+		}
+	}
+
+	m.cumulativeSyncDuration += syncDuration
+	if syncDuration > m.maxSyncDuration {
+		m.maxSyncDuration = syncDuration
+	}
+
+	if jobID > 0 {
+		if jobID > m.maxAssignedJobID {
+			m.maxAssignedJobID = jobID
+		}
+		if m.minTrackedJobID == 0 {
+			m.minTrackedJobID = jobID
+		}
+		m.jobResults[jobID] = durabilityJobResult{done: true, err: err}
+		if len(m.jobResults) > maxJobRetention {
+			cutoff := m.maxAssignedJobID - maxJobRetention
+			for id := range m.jobResults {
+				if id < cutoff {
+					delete(m.jobResults, id)
+				}
+			}
+			if cutoff > m.minTrackedJobID {
+				m.minTrackedJobID = cutoff
+			}
+		}
+	}
+
+	// Update metrics if configured and sync succeeded
+	if m.batchDurableConfigured && err == nil && m.d != nil {
+		m.d.recordDurableCommitMetrics(syncDuration)
+	}
+
+	// Notify subscriptions
+	for ch, targetSeq := range m.subscriptions {
+		if m.firstErr != nil {
+			ch <- m.firstErr
+			delete(m.subscriptions, ch)
+		} else if targetSeq == 0 && m.totalCommits > 0 {
+			ch <- nil
+			delete(m.subscriptions, ch)
+		} else if targetSeq > 0 && targetSeq <= m.highestDurableSeqNum {
+			ch <- nil
+			delete(m.subscriptions, ch)
+		}
+	}
+
+	// Notify waiters
+	m.notifyWaitersLocked()
+
+	m.mu.Unlock()
+
+	// Fire EventListener callback
+	if m.d != nil && m.d.opts.EventListener != nil {
+		info := BatchDurableInfo{
+			JobID:         jobID,
+			SeqNum:        seqNum,
+			Err:           err,
+			ApplyDuration: applyDuration,
+			SyncDuration:  syncDuration,
+			CorrelationID: correlationID,
+			BatchSize:     batchSize,
+			KeyCount:      count,
+		}
+		m.d.opts.EventListener.BatchDurable(info)
+	}
+}
+
+func (m *durabilityManager) notifyWaitersLocked() {
+	var remaining []*durabilityWaiter
+	for _, w := range m.waiters {
+		satisfied := false
+		if m.firstErr != nil {
+			satisfied = true
+		} else if w.isJob {
+			if w.jobID > 0 {
+				res, ok := m.jobResults[w.jobID]
+				if ok && res.done {
+					satisfied = true
+				}
+			}
+		} else {
+			if w.seq == 0 && m.totalCommits > 0 {
+				satisfied = true
+			} else if w.seq > 0 && w.seq <= m.highestDurableSeqNum {
+				satisfied = true
+			}
+		}
+		if satisfied {
+			close(w.ch)
+		} else {
+			remaining = append(remaining, w)
+		}
+	}
+	m.waiters = remaining
+}
+
+func (m *durabilityManager) removeWaiter(target *durabilityWaiter) {
+	for i, w := range m.waiters {
+		if w == target {
+			m.waiters = append(m.waiters[:i], m.waiters[i+1:]...)
+			break
+		}
+	}
+}
+
+func (m *durabilityManager) close() {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if m.firstErr == nil {
+		m.firstErr = ErrClosed
+	}
+
+	for ch := range m.subscriptions {
+		ch <- m.firstErr
+	}
+	m.subscriptions = nil
+
+	for _, w := range m.waiters {
+		close(w.ch)
+	}
+	m.waiters = nil
+}
+
+func (m *durabilityManager) WaitForDurabilityContext(ctx context.Context, seq base.SeqNum) error {
+	if m.disabled {
+		return nil
+	}
+
+	m.mu.Lock()
+	if m.firstErr != nil {
+		err := m.firstErr
+		m.mu.Unlock()
+		return err
+	}
+	if seq == 0 && m.totalCommits > 0 {
+		m.mu.Unlock()
+		return nil
+	}
+	if seq > 0 && seq <= m.highestDurableSeqNum {
+		m.mu.Unlock()
+		return nil
+	}
+
+	if ctx.Err() != nil {
+		if m.firstErr != nil {
+			err := m.firstErr
+			m.mu.Unlock()
+			return err
+		}
+		if seq == 0 && m.totalCommits > 0 {
+			m.mu.Unlock()
+			return nil
+		}
+		if seq > 0 && seq <= m.highestDurableSeqNum {
+			m.mu.Unlock()
+			return nil
+		}
+		m.mu.Unlock()
+		return ctx.Err()
+	}
+
+	w := &durabilityWaiter{
+		seq:   seq,
+		jobID: 0,
+		ch:    make(chan struct{}),
+	}
+	m.waiters = append(m.waiters, w)
+	m.mu.Unlock()
+
+	m.pendingWaiters.Add(1)
+	defer m.pendingWaiters.Add(-1)
+
+	select {
+	case <-w.ch:
+		m.mu.Lock()
+		defer m.mu.Unlock()
+		if m.firstErr != nil {
+			return m.firstErr
+		}
+		return nil
+	case <-ctx.Done():
+		m.mu.Lock()
+		defer m.mu.Unlock()
+		m.removeWaiter(w)
+		if m.firstErr != nil {
+			return m.firstErr
+		}
+		if seq == 0 && m.totalCommits > 0 {
+			return nil
+		}
+		if seq > 0 && seq <= m.highestDurableSeqNum {
+			return nil
+		}
+		return ctx.Err()
+	}
+}
+
+func (m *durabilityManager) WaitForDurabilityBatchContext(ctx context.Context, seqs []base.SeqNum) error {
+	if len(seqs) == 0 {
+		return nil
+	}
+	if m.disabled {
+		return nil
+	}
+
+	var maxSeq base.SeqNum
+	for _, s := range seqs {
+		if s > maxSeq {
+			maxSeq = s
+		}
+	}
+	return m.WaitForDurabilityContext(ctx, maxSeq)
+}
+
+func (m *durabilityManager) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	if m.disabled {
+		return nil
+	}
+	if jobID <= 0 {
+		return errors.Errorf("unknown job ID %d", jobID)
+	}
+
+	m.mu.Lock()
+	if jobID > m.maxAssignedJobID {
+		m.mu.Unlock()
+		return errors.Errorf("unknown job ID %d", jobID)
+	}
+	if jobID < m.minTrackedJobID {
+		m.mu.Unlock()
+		return errors.Errorf("job ID %d has expired", jobID)
+	}
+	res, ok := m.jobResults[jobID]
+	if !ok {
+		m.mu.Unlock()
+		return errors.Errorf("unknown job ID %d", jobID)
+	}
+	if res.done {
+		err := res.err
+		m.mu.Unlock()
+		return err
+	}
+	if m.firstErr != nil {
+		err := m.firstErr
+		m.mu.Unlock()
+		return err
+	}
+
+	if ctx.Err() != nil {
+		if res.done {
+			err := res.err
+			m.mu.Unlock()
+			return err
+		}
+		if m.firstErr != nil {
+			err := m.firstErr
+			m.mu.Unlock()
+			return err
+		}
+		m.mu.Unlock()
+		return ctx.Err()
+	}
+
+	w := &durabilityWaiter{
+		isJob: true,
+		jobID: jobID,
+		ch:    make(chan struct{}),
+	}
+	m.waiters = append(m.waiters, w)
+	m.mu.Unlock()
+
+	m.pendingWaiters.Add(1)
+	defer m.pendingWaiters.Add(-1)
+
+	select {
+	case <-w.ch:
+		m.mu.Lock()
+		defer m.mu.Unlock()
+		res := m.jobResults[jobID]
+		if res.done && res.err != nil {
+			return res.err
+		}
+		if m.firstErr != nil {
+			return m.firstErr
+		}
+		return nil
+	case <-ctx.Done():
+		m.mu.Lock()
+		defer m.mu.Unlock()
+		m.removeWaiter(w)
+		res := m.jobResults[jobID]
+		if res.done {
+			return res.err
+		}
+		if m.firstErr != nil {
+			return m.firstErr
+		}
+		return ctx.Err()
+	}
+}
+
+func (m *durabilityManager) DurableState() (base.SeqNum, error) {
+	if m.disabled {
+		return 0, nil
+	}
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	return m.highestDurableSeqNum, m.firstErr
+}
+
+func (m *durabilityManager) DurabilityNotify(seq base.SeqNum) <-chan error {
+	ch := make(chan error, 1)
+	if m.disabled {
+		ch <- nil
+		return ch
+	}
+
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if m.firstErr != nil {
+		ch <- m.firstErr
+		return ch
+	}
+	if seq == 0 && m.totalCommits > 0 {
+		ch <- nil
+		return ch
+	}
+	if seq > 0 && seq <= m.highestDurableSeqNum {
+		ch <- nil
+		return ch
+	}
+
+	if len(m.subscriptions) >= maxSubscriptions {
+		ch <- errors.New("durability notify subscription limit exceeded")
+		return ch
+	}
+
+	m.subscriptions[ch] = seq
+	return ch
+}
+
+func (m *durabilityManager) DurabilityStats() DurabilityStats {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	return DurabilityStats{
+		HighestDurableSeqNum:   m.highestDurableSeqNum,
+		FirstErr:               m.firstErr,
+		PendingWaiters:         m.pendingWaiters.Load(),
+		TotalDurableCommits:    m.totalDurableCommits,
+		TotalFailedCommits:     m.totalFailedCommits,
+		CumulativeSyncDuration: m.cumulativeSyncDuration,
+		MaxSyncDuration:        m.maxSyncDuration,
+	}
+}
