+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"testing"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+	"github.com/cockroachdb/pebble/vfs"
+	"github.com/stretchr/testify/require"
+)
+
+func TestBatchDurableCallbackAndMetrics(t *testing.T) {
+	memFS := vfs.NewMem()
+	var durableEvents []BatchDurableInfo
+	var mu sync.Mutex
+
+	listener := EventListener{
+		BatchDurable: func(info BatchDurableInfo) {
+			mu.Lock()
+			defer mu.Unlock()
+			durableEvents = append(durableEvents, info)
+		},
+	}
+
+	opts := &Options{
+		FS:            memFS,
+		EventListener: &listener,
+	}
+
+	d, err := Open("", opts)
+	require.NoError(t, err)
+
+	// Sync commit 1
+	wo1 := &WriteOptions{
+		Sync:                true,
+		CommitCorrelationID: 1001,
+	}
+	require.NoError(t, d.Set([]byte("key1"), []byte("val1"), wo1))
+
+	// Sync commit 2
+	wo2 := &WriteOptions{
+		Sync:                true,
+		CommitCorrelationID: 1002,
+	}
+	require.NoError(t, d.Set([]byte("key2"), []byte("val2"), wo2))
+
+	// Non-sync commit (must NOT fire BatchDurable)
+	woNoSync := &WriteOptions{Sync: false}
+	require.NoError(t, d.Set([]byte("key3"), []byte("val3"), woNoSync))
+
